#!/usr/bin/env bash
# blind-score.sh — blind quality scoring for the vanilla-vs-mega-sdd block
# (benchmarks/runbooks/vanilla-vs-megasdd.md §5). For every run listed in <runs>:
#   1. copy the arm's TRACKED files at HEAD (git archive: no history, no node_modules), drop
#      mega-sdd process artefacts (.mega-sdd/, bolts/, CLAUDE.md/AGENTS.md edits are kept — they
#      are part of the delivered repo) and strip the provenance trailer lines that name the arm
#      ("Generated by mega-sdd", "Unit: U-…", "SDD-" lines), then `npm install` OUTSIDE scoring
#   2. give it a random label; the label→run map is written to <out>/labels.json and never
#      shown to the scorer
#   3. score it with a fresh `claude -p` session with the mega-sdd plugins DISABLED (the same
#      settings as the vanilla arm), same model and same prompt for every label: the hidden
#      checklist + the severity rubric; the scorer may run the tests and the build
#   4. parse the scorer's final JSON into <results>/quality.score.json
#      {completion, ac_pass, ac_total, critical, important, minor, rubric, blind_label, scorer_sid}
#
# usage: blind-score.sh <runs> <prd> <checklist> <out-dir> [model]
#   <runs>: one line per run → "<results-dir><TAB><arm-clone>" (TAB: paths may contain spaces)
set -u
RUNS="${1:?runs}"; PRD="${2:?prd}"; CHECK="${3:?checklist}"; OUT="${4:?out dir}"; MODEL="${5:-opus}"
BENCH="$(cd "$(dirname "$0")" && pwd -P)"
mkdir -p "$OUT"
DISABLE='{"enabledPlugins":{"mega-sdd@mega-sdd":false,"mega-sdd-extras@mega-sdd":false}}'
WRAP="$HOME/.claude/commands/mega-sdd.md"; WRAP_BAK="$HOME/.claude/commands/.mega-sdd.md.score-bak"
restore_wrapper() { [ -f "$WRAP_BAK" ] && mv -f "$WRAP_BAK" "$WRAP"; return 0; }
trap restore_wrapper EXIT INT TERM

python3 - "$RUNS" "$OUT/labels.json" <<'EOF'
import json, os, random, string, sys
rows = [l.rstrip('\n').split('\t') for l in open(sys.argv[1]) if l.strip() and not l.startswith('#')]
path = sys.argv[2]
old = json.load(open(path)) if os.path.isfile(path) else {}
used = set(old)
pool = [a + b for a in string.ascii_uppercase for b in string.ascii_uppercase if a + b not in used]
random.SystemRandom().shuffle(pool)
for res, clone in rows:
    if any(v['results'] == res for v in old.values()):
        continue
    old[pool.pop()] = {'results': res, 'clone': clone}
json.dump(old, open(path, 'w'), indent=1)
EOF

PROMPT_FILE="$OUT/scorer-prompt.md"
{
  echo "You are a senior reviewer scoring ONE implementation of the PRD below. Judge ONLY against the PRD and the checklist."
  echo "The implementation is the repository in the current directory. You may read any file and run commands (npm test / npm run test / npx vitest / npm run build, etc.). Do not modify source files."
  echo
  echo "1. For every checklist item give PASS or FAIL with evidence (file:line and/or command + output excerpt)."
  echo "2. Review the code for defects. Severity: Critical (data corruption / security hole / a core requirement does not work), Important (user-visible bug / requirement only partly met), Minor (quality). Every finding needs file:line."
  echo "3. Score 0-100: correctness 40, requirement coverage 30, security 15, maintainability 15."
  echo
  echo "End your reply with exactly one fenced json block and nothing after it:"
  echo '```json'
  echo '{"ac": {"X1": "PASS|FAIL", "...": "..."}, "critical": 0, "important": 0, "minor": 0, "rubric": 0, "findings": [{"severity": "", "where": "", "what": ""}]}'
  echo '```'
  echo
  echo "## PRD"; cat "$PRD"; echo; echo "## Checklist"; cat "$CHECK"
} > "$PROMPT_FILE"

python3 -c "import json,sys; [print(k, v['results'], v['clone'], sep='\t') for k, v in json.load(open(sys.argv[1])).items()]" "$OUT/labels.json" |
while IFS=$'\t' read -r LABEL RES CLONE; do
  [ -f "$RES/quality.score.json" ] && { echo "skip (scored): $LABEL"; continue; }
  S="$OUT/$LABEL"; rm -rf "$S"; mkdir -p "$S/repo"
  git -C "$CLONE" archive HEAD | tar -x -C "$S/repo"
  rm -rf "$S/repo/.mega-sdd"
  find "$S/repo" -type d -name bolts -prune -exec rm -rf {} + 2>/dev/null
  # every TEXT file, dotfiles included (round 1 of the xs block leaked the trailer through .gitignore)
  grep -rIl -E 'Generated by mega-sdd|Unit: U-[0-9]+|SDD-(PROVENANCE|Acceptance)|\.mega-sdd' "$S/repo" 2>/dev/null |
    while IFS= read -r f; do sed -i '' -E '/Generated by mega-sdd|Unit: U-[0-9]+|SDD-(PROVENANCE|Acceptance)|\.mega-sdd/d' "$f"; done
  LEAK=$(grep -rIl -i 'mega-sdd' "$S/repo" 2>/dev/null | head -3)
  [ -n "$LEAK" ] && echo "leak after strip ($LABEL): $LEAK" >&2
  ( cd "$S/repo" && npm install --no-audit --no-fund > ../install.log 2>&1 )
  ( cd "$S/repo" && git init -q . && git add -A >/dev/null 2>&1 && git -c user.email=s@s -c user.name=s commit -qm "label $LABEL" >/dev/null 2>&1 )
  [ -f "$WRAP" ] && mv -f "$WRAP" "$WRAP_BAK"
  SID="$(python3 -c 'import uuid;print(uuid.uuid4())')"
  echo "== $(date -u +%H:%M:%SZ) scoring $LABEL"
  ( cd "$S/repo" && env -u CLAUDECODE -u CLAUDE_CODE_ENTRYPOINT claude -p "$(cat "$PROMPT_FILE")" \
      --model "$MODEL" --session-id "$SID" --settings "$DISABLE" \
      --permission-mode acceptEdits --allowedTools "Bash,Read,Glob,Grep" \
      --output-format stream-json --verbose < /dev/null > "$S/score.jsonl" 2> "$S/score.err" )
  restore_wrapper
  python3 - "$S/score.jsonl" "$RES/quality.score.json" "$LABEL" "$SID" "$S/score.jsonl.purity" <<'EOF'
import json, re, sys
stream, out, label, sid = sys.argv[1:5]
text, roster = None, None
for line in open(stream, encoding='utf-8', errors='replace'):
    try:
        e = json.loads(line)
    except ValueError:
        continue
    if e.get('type') == 'system' and e.get('subtype') == 'init' and roster is None:
        roster = [p.get('name') for p in e.get('plugins') or []]
    if e.get('type') == 'result':
        text = e.get('result') or text
if roster and 'mega-sdd' in roster:
    print(f'SCORER NOT BLIND-SAFE: mega-sdd loaded in scorer {label}'); sys.exit(1)
m = re.findall(r'```json\s*(\{.*?\})\s*```', text or '', re.S)
if not m:
    print(f'no JSON verdict from scorer {label}'); sys.exit(1)
d = json.loads(m[-1])
ac = d.get('ac') or {}
passed = sum(1 for v in ac.values() if str(v).upper().startswith('PASS'))
total = len(ac)
q = {'completion': 1.0 if total and passed == total else (passed / total if total else None),
     'ac_pass': passed, 'ac_total': total, 'ac': ac,
     'critical': d.get('critical'), 'important': d.get('important'), 'minor': d.get('minor'),
     'rubric': d.get('rubric'), 'findings': d.get('findings'), 'blind_label': label, 'scorer_sid': sid}
json.dump(q, open(out, 'w'), indent=1)
print(f"{label}: AC {passed}/{total} critical={q['critical']} important={q['important']} rubric={q['rubric']}")
EOF
done
